package com.lianxibu.site.config;

import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import com.lianxibu.site.service.jobs.*;
import com.lianxibu.site.service.identity.IdentityService;
import com.lianxibu.site.service.settings.SettingsJdbcStore;
import java.util.*;
import javax.sql.DataSource;
import org.junit.jupiter.api.Test;
import org.springframework.boot.test.context.runner.ApplicationContextRunner;
import org.springframework.jdbc.datasource.DataSourceTransactionManager;

class JobsRuntimeConfigurationTest {
    static final String[] FLAGS={"site.browser.enabled","site.content.enabled","site.execution.enabled"};
    ApplicationContextRunner context(DataSource source,SettingsJdbcStore settings){return new ApplicationContextRunner().withUserConfiguration(JobsRuntimeConfiguration.class).withBean(DataSource.class,()->source).withBean(org.springframework.transaction.PlatformTransactionManager.class,()->new DataSourceTransactionManager(source)).withBean(SettingsJdbcStore.class,()->settings);}
    @Test void completeFlagsAssembleOneRealFacadeWithoutSqlOrSettingsRead(){DataSource source=mock(DataSource.class);SettingsJdbcStore settings=mock(SettingsJdbcStore.class);context(source,settings).withPropertyValues(Arrays.stream(FLAGS).map(f->f+"=true").toArray(String[]::new)).run(c->{assertNull(c.getStartupFailure());assertEquals(1,c.getBeansOfType(JobsService.class).size());assertInstanceOf(OperationalJobsService.class,c.getBean(JobsService.class));assertNotNull(c.getBean(OwnerJobsReadService.class));assertInstanceOf(OwnerJobCommandsService.class,c.getBean(OwnerJobsService.Commands.class));assertNotNull(c.getBean(OwnerJobCancelService.class));assertEquals(1,c.getBeansOfType(OwnerJobCloseUnresolvedService.class).size());assertEquals(1,c.getBeansOfType(OwnerJobDiscardResultService.class).size());verifyNoInteractions(source,settings);});}
    @Test void defaultOrEachMissingFlagDoesNotAssembleOrRead(){DataSource source=mock(DataSource.class);SettingsJdbcStore settings=mock(SettingsJdbcStore.class);context(source,settings).run(c->assertTrue(c.getBeansOfType(JobsService.class).isEmpty()));for(String omitted:FLAGS)context(source,settings).withPropertyValues(Arrays.stream(FLAGS).filter(f->!f.equals(omitted)).map(f->f+"=true").toArray(String[]::new)).run(c->assertTrue(c.getBeansOfType(JobsService.class).isEmpty()));verifyNoInteractions(source,settings);}
    @Test void mandatorySettingsDependencyIsNotReplacedWithEmptyConfiguration(){new ApplicationContextRunner().withUserConfiguration(JobsRuntimeConfiguration.class).withBean(DataSource.class,()->mock(DataSource.class)).withBean(org.springframework.transaction.PlatformTransactionManager.class,()->mock(org.springframework.transaction.PlatformTransactionManager.class)).withPropertyValues(Arrays.stream(FLAGS).map(f->f+"=true").toArray(String[]::new)).run(c->assertNotNull(c.getStartupFailure()));}
    @Test void commandPortDelegatesExactAuthorizedValuesAndMissingPortRefuses(){var read=mock(OwnerJobsReadService.class);var command=mock(OwnerJobsService.Commands.class);var service=new OwnerJobsService(read,command);var owner=new IdentityService.Actor("fictional-owner","owner");var create=new JobsService.JobCreate("ad_hoc_ai",new JobsService.ResourceRef("article","fictional-target",null),4,"Fictional request");service.create(owner,create,"fictional-idempotency","fictional-csrf","https://site.example.invalid");verify(command).create(owner,create,"fictional-idempotency","fictional-csrf","https://site.example.invalid");assertThrows(IdentityService.Rejected.class,()->service.create(owner,create,"fictional-key",null,"https://site.example.invalid"));assertEquals(IdentityService.Refusal.TEMPORARILY_UNAVAILABLE,assertThrows(IdentityService.Rejected.class,()->new OwnerJobsService(read,null).create(owner,create,"fictional-key","fictional-csrf","https://site.example.invalid")).refusal());assertThrows(IdentityService.Rejected.class,()->service.get(new IdentityService.Actor("fictional-member","member"),"fictional-job"));verifyNoInteractions(read);}
    @Test void fullBusinessFlagsRequireReadinessAndConstructRecoveryWithoutAnyIo(){DataSource source=mock(DataSource.class);SettingsJdbcStore settings=mock(SettingsJdbcStore.class);var readiness=mock(DispatchReadinessService.class);String[] flags={"site.browser.enabled=true","site.content.enabled=true","site.execution.enabled=true","site.articles.enabled=true","site.sources.enabled=true"};context(source,settings).withPropertyValues(flags).run(c->assertNotNull(c.getStartupFailure()));context(source,settings).withBean(DispatchReadinessService.class,()->readiness).withPropertyValues(flags).run(c->{assertNull(c.getStartupFailure());assertEquals(1,c.getBeansOfType(OwnerJobRecoverService.class).size());assertEquals(1,c.getBeansOfType(JobsService.class).size());});verifyNoInteractions(source,settings,readiness);}
}
